import React from 'react';
import {AbsoluteFill} from 'remotion';
import {useS, en, idx, T, DUR, Camara, Textura, Profundidad, Brillo, Paso, tono, Chip, Contador, Ondas, Destello, golpe, interpolate, clamp, h, FONT} from './kit';

// ---------- utilidades ----------
const cl = (v: number, a = 0, b = 1) => Math.max(a, Math.min(b, v));
const eo = (x: number) => 1 - Math.pow(1 - cl(x), 3);
const eio = (x: number) => { const k = cl(x); return k < 0.5 ? 4 * k * k * k : 1 - Math.pow(-2 * k + 2, 3) / 2; };
const ro = (s: number, a: number, b: number) => cl((s - a) / (b - a));
const P = (t: number, x: number, y: number, z: number) => ({t, x: cl(x, 540 / z, 1080 - 540 / z), y: cl(y, 1000 / z, 1920 - 920 / z), zoom: z});
const scr = (c: {x: number; y: number; zoom: number}, x: number, y: number) => ({x: 540 + (x - c.x) * c.zoom, y: 1000 + (y - c.y) * c.zoom});
const GOLD = '#FFC83D';
const RED = '#FF4D4D';
const GREEN = '#50DC8C';
const PIELES = [['#f3d2b0', '#e3b88e', '#c99a6e'], ['#e0a878', '#c98f5e', '#9c6a40'], ['#b57b52', '#8a5a36', '#5e3a22'], ['#7a4f2c', '#5e3a22', '#3d2414'], ['#fffaf0', '#ece2c8', '#c4b68e']];
// SFX: nunca dos a menos de 0,27 s aunque la voz real cambie los tiempos
const fix = (l: {t: number; s: string}[]) => {
  const o: {t: number; s: string}[] = [];
  let last = -9;
  [...l].sort((a, b) => a.t - b.t).forEach((e) => { if (e.t - last >= 0.27) { o.push(e); last = e.t; } });
  return o;
};
const sf = (p: string, s: string, o = 0, n = 1) => ({t: en(p, n) + o, s});

// ---------- tiempos (todo atado a palabras del guion) ----------
const ALTURA = en('altura'), ALQUILADO = en('alquilado'), MARCA1 = en('marca'), PAGO1 = en('pago'), AHI = en('ahi');
const MARCAS = en('marcas'), SUPER = en('supermercado'), ENTRAR1 = en('entrar'), ESTANTES = en('estantes'), MEJORES = en('mejores'), LUGARES = en('lugares'), LLAMA = en('llama'), ESPACIO = en('espacio');
const ES = en('es'), INVENTO = en('invento'), COMISION = en('comision'), DOS = en('dos'), TRES = en('tres'), FABRICANTES = en('fabricantes'), ENTRAR2 = en('entrar', 2), QUEDARSE = en('quedarse');
const Y3 = en('y', 3), SALE = en('sale'), VENDE = en('vende'), MARCA2 = en('marca', 2), FORMA = en('forma'), TERMINA = en('termina'), PAGAS = en('pagas');
const E5S = T(idx('eso') - 1), PRIMERO = en('primero'), BARATO1 = en('barato'), BARATO2 = en('barato', 2), ABAJO1 = en('abajo'), PISO = en('piso'), ARRIBA = en('arriba'), ESTIRARTE = en('estirarte');
const LA3 = en('la', 3), PROXIMA = en('proxima'), AGARRAR = en('agarrar'), MANO = en('mano'), ABAJO2 = en('abajo', 2), COMPARA = en('compara'), PRECIO = en('precio'), KILO = en('kilo'), LITRO = en('litro'), ETIQUETA = en('etiqueta');
const DALE = en('dale'), ABAJO3 = en('abajo', 3), AGARRAS = en('agarras'), ENVIASELO = en('enviaselo');

// ---------- piezas dibujadas ----------
const Polvo: React.FC<{n?: number; color?: string}> = ({n = 24, color = 'rgba(255,255,255,0.55)'}) => {
  const {s} = useS();
  return (
    <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
      {Array.from({length: n}).map((_, i) => {
        const x = h(i * 3 + 1) * 1080 + Math.sin(s * 0.6 + i) * 30;
        const y = (((h(i * 7 + 2) * 1920 - s * (12 + h(i) * 22)) % 1920) + 1920) % 1920;
        return <circle key={i} cx={x} cy={y} r={2 + h(i * 5) * 4} fill={color} opacity={0.2 + h(i * 11) * 0.35} />;
      })}
    </svg>
  );
};

// mano con indice opcional; manga = color de la manga; largo = manga extra hacia abajo
const Mano: React.FC<{x: number; y: number; r?: number; k?: number; dedo?: boolean; piel?: number; manga?: string; largo?: number}> = ({x, y, r = 0, k = 1, dedo = true, piel = 1, manga, largo = 0}) => {
  const C = PIELES[piel];
  const F = `url(#pm${piel})`;
  const L = C[2];
  return (
    <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
      <defs><linearGradient id={`pm${piel}`} x1="0" y1="0" x2="1" y2="0"><stop offset="0%" stopColor={C[0]} /><stop offset="55%" stopColor={C[1]} /><stop offset="100%" stopColor={C[2]} /></linearGradient></defs>
      <rect x={-64} y={80} width={128} height={420} rx={50} fill={F} stroke={L} strokeWidth={4} />
      <rect x={-80} y={-70} width={160} height={190} rx={56} fill={F} stroke={L} strokeWidth={4} />
      {[[-58, 70], [-20, 55], [20, 60], [58, 75]].map(([fx, fl], i) => (
        <rect key={i} x={fx - 17} y={-70 - (i === 1 && dedo ? 150 : fl)} width={34} height={(i === 1 && dedo ? 150 : fl) + 40} rx={17} fill={F} stroke={L} strokeWidth={3} />
      ))}
      <rect x={-128} y={-20} width={34} height={110} rx={17} fill={F} stroke={L} strokeWidth={3} transform="rotate(-38 -110 60)" />
      <path d="M -80 -20 Q -30 -50 20 -20" stroke="rgba(255,255,255,0.28)" strokeWidth={6} fill="none" strokeLinecap="round" />
      {manga && (
        <g>
          <rect x={-76} y={118} width={152} height={420 + largo} rx={16} fill={manga} stroke="rgba(0,0,0,0.4)" strokeWidth={3} />
          <rect x={-80} y={104} width={160} height={34} rx={9} fill="#f4f0e6" stroke="#bdb7a4" strokeWidth={3} />
        </g>
      )}
    </g>
  );
};

const Moneda: React.FC<{x: number; y: number; k?: number; r?: number}> = ({x, y, k = 1, r = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <ellipse cy={44} rx={30} ry={8} fill="rgba(0,0,0,0.25)" />
    <circle r={38} fill="#e8a516" stroke="#7a5a10" strokeWidth={4} />
    <circle r={29} fill="#ffd45a" stroke="#c98d10" strokeWidth={3} />
    <text y={13} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={38} fill="#8a5d08">$</text>
    <path d="M -24 -12 Q -10 -30 8 -26" stroke="rgba(255,255,255,0.7)" strokeWidth={5} fill="none" strokeLinecap="round" />
  </g>
);

// etiqueta de precio con cordon
const Etq: React.FC<{x: number; y: number; txt: string; r?: number; k?: number; fs?: number}> = ({x, y, txt, r = 0, k = 1, fs = 46}) => (
  <g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
    <path d="M 0 -150 Q -30 -100 0 -60" stroke="#8a6a10" strokeWidth={5} fill="none" />
    <path d="M -90 -60 L 90 -60 L 120 -20 L 120 70 L -120 70 L -120 -20 Z" fill="rgba(0,0,0,0.3)" transform="translate(8 10)" />
    <path d="M -90 -60 L 90 -60 L 120 -20 L 120 70 L -120 70 L -120 -20 Z" fill="#f6ecd2" stroke="#b79a52" strokeWidth={5} />
    <circle cy={-34} r={11} fill="#3a2a00" />
    <text y={48} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={fs} fill="#5a4520">{txt}</text>
  </g>
);

// cartera de cuero; abre 0..1 (la solapa baja), lleno 0..1 (billetes que asoman)
const CarteraAb: React.FC<{x: number; y: number; k?: number; abre: number; lleno: number}> = ({x, y, k = 1, abre, lleno}) => {
  const n = Math.round(lleno * 5);
  return (
    <g transform={`translate(${x} ${y}) scale(${k})`}>
      <defs><linearGradient id="cuero18" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8a5a34" /><stop offset="60%" stopColor="#5f3a1f" /><stop offset="100%" stopColor="#3d2312" /></linearGradient></defs>
      <ellipse cx={0} cy={140} rx={210} ry={26} fill="rgba(0,0,0,0.4)" />
      {n > 0 && Array.from({length: n}).map((_, i) => (
        <rect key={i} x={-130 + i * 52 - (n - 1) * 0} y={-150 - lleno * 70 - (i % 2) * 18} width={92} height={140} rx={6} fill={i % 2 ? '#6fc27a' : '#58b068'} stroke="#2f6a3a" strokeWidth={3} transform={`rotate(${(i - 2) * 5} ${-84 + i * 52} -20)`} />
      ))}
      <rect x={-190} y={-120} width={380} height={250} rx={30} fill="url(#cuero18)" stroke="#2c180a" strokeWidth={5} />
      {abre > 0.03 && <rect x={-170} y={-110} width={340} height={100 + 130 * abre} rx={14} fill="#241206" opacity={0.9} />}
      {abre > 0.03 && Array.from({length: 3}).map((_, i) => <circle key={i} cx={-90 + i * 90} cy={-60 + abre * 30} r={24} fill={GOLD} stroke="#7a5a10" strokeWidth={3} />)}
      <g transform={`translate(0 ${abre * 175}) scale(1 ${1 - abre * 0.55})`}>
        <rect x={-190} y={-40} width={380} height={170} rx={26} fill="url(#cuero18)" stroke="#2c180a" strokeWidth={5} />
        <rect x={-170} y={-22} width={340} height={134} rx={16} fill="none" stroke="#c9a074" strokeWidth={3} strokeDasharray="12 9" opacity={0.85} />
        <rect x={120} y={10} width={70} height={64} rx={14} fill={GOLD} stroke="#2c180a" strokeWidth={4} />
      </g>
      <path d="M -190 -60 Q 0 -30 190 -60 L 190 -90 Q 0 -120 -190 -90 Z" fill="rgba(255,255,255,0.10)" />
    </g>
  );
};

// caja de producto; (x,y) = esquina inferior izquierda
const Caja: React.FC<{x: number; y: number; w: number; hh: number; c: string; lujo: boolean; i: number}> = ({x, y, w, hh, c, lujo, i}) => (
  <g transform={`translate(${x} ${y})`}>
    <rect x={4} y={-hh + 6} width={w} height={hh} rx={8} fill="rgba(0,0,0,0.22)" />
    <rect x={0} y={-hh} width={w} height={hh} rx={8} fill={c} stroke="rgba(0,0,0,0.38)" strokeWidth={4} />
    <rect x={0} y={-hh} width={w * 0.3} height={hh} rx={8} fill="rgba(255,255,255,0.16)" />
    {lujo ? (
      <g>
        <rect x={w * 0.12} y={-hh * 0.62} width={w * 0.76} height={hh * 0.3} rx={6} fill="rgba(255,255,255,0.9)" />
        <circle cx={w * 0.5} cy={-hh * 0.8} r={w * 0.13} fill="rgba(255,255,255,0.95)" />
        <circle cx={w * 0.5} cy={-hh * 0.8} r={w * 0.06} fill={c} />
        <path d={`M ${w * 0.08} ${-hh * 0.95} L ${w * 0.4} ${-hh * 0.95} L ${w * 0.18} ${-hh * 0.3} L ${w * 0.08} ${-hh * 0.3} Z`} fill="rgba(255,255,255,0.22)" />
      </g>
    ) : (
      <g>
        <rect x={w * 0.14} y={-hh * 0.58} width={w * 0.72} height={hh * 0.26} rx={4} fill="rgba(255,255,255,0.55)" />
        {[0, 1].map((j) => <rect key={j} x={w * 0.2} y={-hh * 0.52 + j * 16} width={w * (0.5 - j * 0.15)} height={6} rx={3} fill="rgba(60,60,60,0.55)" />)}
      </g>
    )}
  </g>
);

// estante de supermercado; tablas en 300, 700, 1100 y 1500. glow = brillo dorado de las filas buenas.
const BRD = [300, 700, 1100, 1500];
const COLS = ['#e8453c', '#2f7dd1', '#f2b632', '#3fae5a', '#8e4fc4', '#ec7d2c', '#1fa8a0', '#d94f86'];
const BEIS = ['#cdbfa2', '#b9b4a6', '#c8c0b0', '#d6cdb8', '#bdb09a'];
const Estante: React.FC<{glow?: number}> = ({glow = 0}) => {
  const {s} = useS();
  const filas = BRD.map((B, r) => {
    const out: {x: number; w: number; hh: number; c: string}[] = [];
    let x = 70, i = 0;
    while (x < 940) {
      const w = 96 + h(r * 40 + i) * 70;
      const alto = r === 0 ? 150 + h(r * 9 + i * 3) * 60 : r === 3 ? 170 + h(r * 9 + i * 3) * 60 : 230 + h(r * 9 + i * 3) * 100;
      out.push({x, w, hh: alto, c: r === 3 ? BEIS[(i + r) % BEIS.length] : COLS[(i * 3 + r * 2) % COLS.length]});
      x += w + 12; i++;
    }
    return {B, r, items: out};
  });
  return (
    <g>
      <defs>
        <linearGradient id="paredE18" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#e9f0f6" /><stop offset="100%" stopColor="#b3c3d2" /></linearGradient>
        <linearGradient id="brilloE18" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#ffd45a" stopOpacity={0} /><stop offset="50%" stopColor="#ffd45a" stopOpacity={0.55} /><stop offset="100%" stopColor="#ffd45a" stopOpacity={0} /></linearGradient>
      </defs>
      <rect x={0} y={0} width={1080} height={1700} fill="url(#paredE18)" />
      {[0, 1, 2].map((i) => <rect key={i} x={110 + i * 360} y={0} width={140} height={14} rx={7} fill="#fffbe8" opacity={0.9} />)}
      <rect x={0} y={1640} width={1080} height={280} fill="#8d98a4" />
      {Array.from({length: 8}).map((_, i) => <line key={i} x1={i * 170 - 60} y1={1640} x2={i * 260 - 400} y2={1920} stroke="rgba(255,255,255,0.22)" strokeWidth={4} />)}
      <rect x={0} y={1790} width={1080} height={5} fill="rgba(255,255,255,0.18)" />
      {filas.map(({B, r, items}) => (
        <g key={r}>
          {items.map((it, i) => <Caja key={i} x={it.x} y={B} w={it.w} hh={it.hh} c={it.c} lujo={r !== 3} i={i} />)}
          <rect x={40} y={B} width={1000} height={18} fill="#c6d0da" stroke="#7d8997" strokeWidth={3} />
          <rect x={40} y={B + 18} width={1000} height={34} fill="#7d8997" />
          {Array.from({length: 6}).map((_, j) => (
            <g key={j}>
              <rect x={70 + j * 160} y={B + 22} width={110} height={26} rx={4} fill="#fffdf2" />
              <text x={125 + j * 160} y={B + 43} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={20} fill="#33404d">{(2 + h(r * 7 + j) * 3).toFixed(2)}</text>
            </g>
          ))}
        </g>
      ))}
      <rect x={0} y={0} width={46} height={1650} fill="#5e6d7e" /><rect x={1034} y={0} width={46} height={1650} fill="#5e6d7e" />
      <rect x={0} y={1552} width={1080} height={88} fill="#4c5663" />
      {r0(s)}
      <rect x={46} y={380} width={988} height={760} fill="url(#brilloE18)" opacity={glow * (0.8 + 0.2 * Math.sin(s * 5))} />
    </g>
  );
};
// brillo que recorre las filas buenas (barrido de luz)
const r0 = (s: number) => {
  const x = ((s * 160) % 1700) - 300;
  return <polygon points={`${x},300 ${x + 90},300 ${x - 40},1150 ${x - 130},1150`} fill="rgba(255,255,255,0.16)" />;
};

// letrero de llave dorada que se balancea; cuelga de (x,y)
const Letrero: React.FC<{x: number; y: number; a: number; t0: number}> = ({x, y, a, t0}) => {
  const {s} = useS();
  const sw = 9 * Math.sin((s - t0) * 2.7) * (0.6 + 0.4 * Math.exp(-(s - t0) * 0.4));
  const caida = (1 - cl(a)) * -900;
  return (
    <g transform={`translate(${x} ${y + caida}) rotate(${sw})`}>
      <line x1={-60} y1={0} x2={0} y2={90} stroke="#8a6a10" strokeWidth={6} /><line x1={60} y1={0} x2={0} y2={90} stroke="#8a6a10" strokeWidth={6} />
      <rect x={-150} y={84} width={300} height={360} rx={30} fill="rgba(0,0,0,0.3)" transform="translate(10 12)" />
      <rect x={-150} y={84} width={300} height={360} rx={30} fill="#f3b82e" stroke="#7a5a10" strokeWidth={8} />
      <rect x={-130} y={104} width={260} height={320} rx={20} fill="none" stroke="#fff0a8" strokeWidth={4} />
      <circle cx={0} cy={190} r={52} fill="none" stroke="#7a4a00" strokeWidth={22} />
      <rect x={-12} y={238} width={24} height={110} rx={8} fill="#7a4a00" />
      <rect x={-12} y={300} width={64} height={22} rx={6} fill="#7a4a00" /><rect x={-12} y={338} width={48} height={22} rx={6} fill="#7a4a00" />
      <text y={406} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={34} fill="#7a4a00">ALQUILADO</text>
      <path d="M -110 130 Q -60 100 -10 112" stroke="rgba(255,255,255,0.6)" strokeWidth={8} fill="none" strokeLinecap="round" />
    </g>
  );
};

// camion de marca (de lado): cabina + caja de color
const Camion: React.FC<{x: number; y: number; c: string; k?: number}> = ({x, y, c, k = 1}) => (
  <g transform={`translate(${x} ${y}) scale(${k})`}>
    <ellipse cy={6} rx={170} ry={14} fill="rgba(0,0,0,0.3)" />
    <rect x={-150} y={-170} width={210} height={150} rx={12} fill={c} stroke="rgba(0,0,0,0.4)" strokeWidth={5} />
    <rect x={-132} y={-120} width={174} height={40} rx={8} fill="rgba(255,255,255,0.88)" />
    <circle cx={-45} cy={-146} r={14} fill="rgba(255,255,255,0.9)" />
    <path d="M 60 -120 L 118 -120 L 150 -70 L 150 -20 L 60 -20 Z" fill="#dfe6ee" stroke="rgba(0,0,0,0.4)" strokeWidth={5} />
    <path d="M 74 -108 L 112 -108 L 134 -74 L 74 -74 Z" fill="#7fb4e0" />
    <rect x={-150} y={-30} width={300} height={14} fill="#4c5663" />
    {[-90, 90].map((cx) => <g key={cx}><circle cx={cx} cy={-8} r={28} fill="#2a2f36" /><circle cx={cx} cy={-8} r={12} fill="#aab4bf" /></g>)}
  </g>
);

// ================= SITIO A: el estante alquilado y los pagos (E1 y E2) =================
const SA_CAM = [P(0, 540, 1060, 1.08), P(ALQUILADO, 540, 940, 1.4), P(MARCA1, 540, 960, 1.55), P(AHI, 540, 1050, 1.45), P(MARCAS, 540, 1250, 1.25), P(SUPER, 700, 1340, 1.3), P(ENTRAR1, 720, 1330, 1.3), P(ESTANTES, 540, 1000, 1.05), P(MEJORES, 540, 900, 1.0), P(ESPACIO, 540, 820, 1.2)];
const SA_END = SA_CAM[9];
const SitioA: React.FC = () => {
  const {s, spr} = useS();
  const let0 = spr(ALQUILADO, 9, 120);
  const tc = s - MARCA1;
  const caida = tc < 0 ? -1 : Math.min(tc / 0.55, 1);
  const cy = -140 + caida * (1075 + 140);
  const reb = tc > 0.55 ? Math.abs(Math.sin((tc - 0.55) * 11)) * 60 * Math.exp(-(tc - 0.55) * 4) : 0;
  const glow = 0.28 + 0.72 * eo(ro(s, MEJORES, MEJORES + 0.7));
  const ventana = 1;
  return (
    <AbsoluteFill>
      <Camara paradas={SA_CAM}>
        <Textura tipo="papel" base="linear-gradient(180deg, #dfe8ee 0%, #b9c7d3 100%)" linea="rgba(255,255,255,0.35)" luz="rgba(255,255,255,0.25)" semilla={41} />
        <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>
          <Estante glow={glow} />
          {/* ventanilla del supermercado */}
          {s > MARCAS - 0.5 && (
            <g transform={`translate(${880 + (1 - eo(ro(s, MARCAS - 0.4, MARCAS + 0.3))) * 400} 1700)`}>
              <rect x={-120} y={-250} width={240} height={250} rx={14} fill="#2f6f4a" stroke="#143a26" strokeWidth={6} />
              <path d="M -140 -250 L 140 -250 L 120 -310 L -120 -310 Z" fill="#e8453c" stroke="#7a1a14" strokeWidth={5} />
              {[0, 1, 2, 3].map((i) => <path key={i} d={`M ${-120 + i * 60} -310 L ${-90 + i * 60} -310 L ${-100 + i * 60} -250 L ${-120 + i * 60} -250 Z`} fill="#fff" opacity={0.85} />)}
              <rect x={-86} y={-210} width={172} height={110} rx={10} fill="#0e1f16" stroke="#6fb88a" strokeWidth={5} />
              <rect x={-110} y={-96} width={220} height={22} rx={6} fill="#8a5a2c" stroke="#2c180a" strokeWidth={4} />
              <text y={-30} textAnchor="middle" fontFamily={FONT} fontWeight={800} fontSize={30} fill="#fff">SUPER</text>
            </g>
          )}
          {/* camiones que llegan y sueltan monedas */}
          {[0, 1, 2].map((i) => {
            const t0 = MARCAS + i * 0.5;
            const p = eo(ro(s, t0 - 0.2, t0 + 0.9));
            if (s < t0 - 0.2) return null;
            const tx = [160, 450, 700][i];
            return <Camion key={i} x={-380 + (tx + 380) * p} y={1890 - i * 4} c={['#d94f86', '#2f7dd1', '#ec7d2c'][i]} k={0.62} />;
          })}
          {Array.from({length: 9}).map((_, i) => {
            const t0 = SUPER - 0.2 + i * 0.3;
            const p = (s - t0) / 0.7;
            if (p < 0 || p > 1) return null;
            const fx = [200, 480, 740][i % 3] + 60;
            return <Moneda key={i} x={fx + (860 - fx) * p} y={1780 + (1560 - 1780) * p - 330 * Math.sin(Math.PI * p)} k={0.55} r={p * 540} />;
          })}
          {/* la moneda que cae en el estante en "marca" */}
          {tc > -0.01 && tc < 1.6 && <Moneda x={620} y={cy - reb} k={1.5 - 0.2 * caida} r={caida * 400} />}
